#include "converter.h"

#include "display_info.h"
#include "log_config.h"

#include <cmath>
#include <cwchar>

#include "hdr_to_sdr_ps.h" // g_PSMain, generated by fxc at build time
#include "hdr_to_sdr_vs.h" // g_VSMain

namespace {

// Must match cbuffer Params in hdr_to_sdr.hlsl.
struct Params {
    float scale;
    float knee;
    float invW2;
    UINT mode;
};
static_assert(sizeof(Params) % 16 == 0);

constexpr UINT kModeShoulder = 1;
constexpr UINT kModeSrgb = 2;
constexpr ULONGLONG kWhiteRefreshMs = 1000;

// Holds the device's multithread lock for the scope, if the app turned protection on.
class MultithreadLock {
public:
    explicit MultithreadLock(ID3D11Multithread* mt)
        : mt_(mt && mt->GetMultithreadProtected() ? mt : nullptr)
    {
        if (mt_)
            mt_->Enter();
    }
    ~MultithreadLock()
    {
        if (mt_)
            mt_->Leave();
    }
    MultithreadLock(const MultithreadLock&) = delete;
    MultithreadLock& operator=(const MultithreadLock&) = delete;

private:
    ID3D11Multithread* mt_;
};

bool Failed(HRESULT hr, const char* what)
{
    if (SUCCEEDED(hr))
        return false;
    Log("converter: %s failed, hr=0x%08lX", what, static_cast<unsigned long>(hr));
    return true;
}

} // namespace

bool Converter::Init(ID3D11Device* device, const DXGI_OUTPUT_DESC1& output, DXGI_FORMAT outFormat)
{
    device_ = device;
    device_->GetImmediateContext(&ctx_);
    if (Failed(device_.As(&device1_), "ID3D11Device1") || Failed(ctx_.As(&ctx1_), "ID3D11DeviceContext1"))
        return false;
    ctx_.As(&multithread_); // optional

    // Our own context state: swapping it in hides the app's bindings, swapping back restores them.
    const UINT stateFlags = (device_->GetCreationFlags() & D3D11_CREATE_DEVICE_SINGLETHREADED)
                                ? D3D11_1_CREATE_DEVICE_CONTEXT_STATE_SINGLETHREADED
                                : 0;
    const D3D_FEATURE_LEVEL level = device_->GetFeatureLevel();
    if (Failed(device1_->CreateDeviceContextState(stateFlags, &level, 1, D3D11_SDK_VERSION,
                                                  __uuidof(ID3D11Device1), nullptr, &state_),
               "CreateDeviceContextState"))
        return false;

    if (Failed(device_->CreateVertexShader(g_VSMain, sizeof(g_VSMain), nullptr, &vs_), "CreateVertexShader") ||
        Failed(device_->CreatePixelShader(g_PSMain, sizeof(g_PSMain), nullptr, &ps_), "CreatePixelShader"))
        return false;

    D3D11_BUFFER_DESC cb{};
    cb.ByteWidth = sizeof(Params);
    cb.Usage = D3D11_USAGE_DEFAULT;
    cb.BindFlags = D3D11_BIND_CONSTANT_BUFFER;
    if (Failed(device_->CreateBuffer(&cb, nullptr, &constants_), "CreateBuffer"))
        return false;

    outFormat_ = outFormat;
    wcsncpy_s(gdiName_, output.DeviceName, _TRUNCATE);
    if (Cfg().peakOverrideNits > 0)
        peakNits_ = Cfg().peakOverrideNits;
    else if (output.MaxLuminance > 0)
        peakNits_ = output.MaxLuminance;
    RefreshWhiteLevel(true);
    return true;
}

void Converter::RefreshWhiteLevel(bool force)
{
    const ULONGLONG now = GetTickCount64();
    if (!force && now - lastWhiteQuery_ < kWhiteRefreshMs)
        return;
    lastWhiteQuery_ = now;

    float nits = Cfg().sdrWhiteOverrideNits;
    if (nits <= 0) {
        nits = QuerySdrWhiteNits(gdiName_);
        if (nits <= 0) {
            if (force)
                Log("converter: could not read the SDR white level of %ls, assuming 80 nits", gdiName_);
            nits = 80.0f;
        }
    }
    if (force || std::fabs(nits - sdrWhiteNits_) > 0.5f) {
        if (!force)
            Log("SDR white level of %ls changed: %.0f -> %.0f nits", gdiName_, sdrWhiteNits_, nits);
        sdrWhiteNits_ = nits;
    }
}

void Converter::UpdateConstants()
{
    Params p{};
    p.scale = 80.0f / sdrWhiteNits_;
    p.knee = Cfg().knee;
    p.mode = (outFormat_ == DXGI_FORMAT_B8G8R8A8_UNORM) ? kModeSrgb : 0;

    // w: where the display peak lands after scaling. The shoulder maps [knee, w] onto [knee, 1].
    const float w = peakNits_ / sdrWhiteNits_;
    if (p.knee < 0.999f && w > 1.0001f) {
        const float W = (w - p.knee) / (1.0f - p.knee);
        p.invW2 = 1.0f / (W * W);
        p.mode |= kModeShoulder;
    }
    ctx_->UpdateSubresource(constants_.Get(), 0, nullptr, &p, 0, 0);
}

bool Converter::EnsureOutput(UINT width, UINT height)
{
    if (out_ && width == outWidth_ && height == outHeight_)
        return true;
    out_.Reset();
    outRtv_.Reset();
    valid_ = false;

    D3D11_TEXTURE2D_DESC d{};
    d.Width = width;
    d.Height = height;
    d.MipLevels = 1;
    d.ArraySize = 1;
    d.Format = outFormat_;
    d.SampleDesc.Count = 1;
    d.Usage = D3D11_USAGE_DEFAULT;
    d.BindFlags = D3D11_BIND_RENDER_TARGET | D3D11_BIND_SHADER_RESOURCE;
    if (Failed(device_->CreateTexture2D(&d, nullptr, &out_), "CreateTexture2D(output)") ||
        Failed(device_->CreateRenderTargetView(out_.Get(), nullptr, &outRtv_), "CreateRenderTargetView")) {
        out_.Reset();
        return false;
    }
    outWidth_ = width;
    outHeight_ = height;
    return true;
}

bool Converter::EnsureSrcCopy(const D3D11_TEXTURE2D_DESC& srcDesc)
{
    if (srcCopy_) {
        D3D11_TEXTURE2D_DESC d;
        srcCopy_->GetDesc(&d);
        if (d.Width == srcDesc.Width && d.Height == srcDesc.Height)
            return true;
    }
    srcCopy_.Reset();
    srcCopySrv_.Reset();

    D3D11_TEXTURE2D_DESC d{};
    d.Width = srcDesc.Width;
    d.Height = srcDesc.Height;
    d.MipLevels = 1;
    d.ArraySize = 1;
    d.Format = DXGI_FORMAT_R16G16B16A16_FLOAT;
    d.SampleDesc.Count = 1;
    d.Usage = D3D11_USAGE_DEFAULT;
    d.BindFlags = D3D11_BIND_SHADER_RESOURCE;
    if (Failed(device_->CreateTexture2D(&d, nullptr, &srcCopy_), "CreateTexture2D(source copy)") ||
        Failed(device_->CreateShaderResourceView(srcCopy_.Get(), nullptr, &srcCopySrv_), "CreateShaderResourceView(copy)")) {
        srcCopy_.Reset();
        return false;
    }
    Log("converter: desktop texture is not shader-readable, using an intermediate copy");
    return true;
}

ID3D11Texture2D* Converter::Convert(ID3D11Texture2D* src)
{
    MultithreadLock lock(multithread_.Get());

    D3D11_TEXTURE2D_DESC sd;
    src->GetDesc(&sd);
    if (sd.Format != DXGI_FORMAT_R16G16B16A16_FLOAT && sd.Format != DXGI_FORMAT_R16G16B16A16_TYPELESS) {
        Log("converter: unexpected desktop format %d", sd.Format);
        return nullptr;
    }
    if (!EnsureOutput(sd.Width, sd.Height))
        return nullptr;

    ComPtr<ID3D11ShaderResourceView> srv;
    if (sd.BindFlags & D3D11_BIND_SHADER_RESOURCE) {
        D3D11_SHADER_RESOURCE_VIEW_DESC vd{};
        vd.Format = DXGI_FORMAT_R16G16B16A16_FLOAT;
        vd.ViewDimension = D3D11_SRV_DIMENSION_TEXTURE2D;
        vd.Texture2D.MipLevels = 1;
        if (Failed(device_->CreateShaderResourceView(src, &vd, &srv), "CreateShaderResourceView"))
            return nullptr;
    } else {
        if (!EnsureSrcCopy(sd))
            return nullptr;
        ctx_->CopyResource(srcCopy_.Get(), src);
        srv = srcCopySrv_;
    }

    RefreshWhiteLevel(false);
    UpdateConstants();

    ComPtr<ID3DDeviceContextState> appState;
    ctx1_->SwapDeviceContextState(state_.Get(), &appState);

    const D3D11_VIEWPORT vp{0.0f, 0.0f, float(sd.Width), float(sd.Height), 0.0f, 1.0f};
    ID3D11Buffer* cb = constants_.Get();
    ID3D11ShaderResourceView* srvs[] = {srv.Get()};
    ID3D11RenderTargetView* rtvs[] = {outRtv_.Get()};
    ctx_->IASetPrimitiveTopology(D3D11_PRIMITIVE_TOPOLOGY_TRIANGLELIST);
    ctx_->VSSetShader(vs_.Get(), nullptr, 0);
    ctx_->PSSetShader(ps_.Get(), nullptr, 0);
    ctx_->PSSetConstantBuffers(0, 1, &cb);
    ctx_->PSSetShaderResources(0, 1, srvs);
    ctx_->RSSetViewports(1, &vp);
    ctx_->OMSetRenderTargets(1, rtvs, nullptr);
    ctx_->Draw(3, 0);

    // Unbind so our state object doesn't keep the desktop frame or output bound.
    ID3D11ShaderResourceView* nullSrv = nullptr;
    ctx_->PSSetShaderResources(0, 1, &nullSrv);
    ctx_->OMSetRenderTargets(0, nullptr, nullptr);

    ctx1_->SwapDeviceContextState(appState.Get(), nullptr);

    valid_ = true;
    return out_.Get();
}
